[1445] = { title = "The Temple of Atal'Hakkar", body = "Fel'Zerul in Stonard asked for 20 Fetishes of Hakkar." },
[2973] = { title = "A New Cloak's Sheen", body = "Krueg Skullsplitter in Camp Mojache asked for 10 Iridescent Sprite Darter Wings." },
[2974] = { title = "A Grim Discovery", body = "Krueg Skullsplitter asked for 20 Grimtotem Horns in Camp Mojache." },
[2976] = { title = "A Grim Discovery", body = "Krueg Skullsplitter sent the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar." },
[2981] = { title = "A Threat in Feralas", body = "Belgrom Rockmaul sent the word to Rok Orhan in Camp Mojache." },
[2975] = { title = "The Ogres of Feralas", body = "Rok Orhan in Camp Mojache asked for the death of 10 Gordunni Ogres, 10 Gordunni Ogre-Magi and 5 Gordunni Brutes." },
[2980] = { title = "The Ogres of Feralas", body = "Rok Orhan asked for the death of 10 Gordunni Shaman, 10 Gordunni Warlocks and 5 Gordunni Maulers in Camp Mojache." },
[2978] = { title = "The Gordunni Scroll", body = "The Gordunni Scroll was brought to Rok Orhan in Camp Mojache." },
[2979] = { title = "Dark Ceremony", body = "Rok Orhan in Camp Mojache asked for a Gordunni Orb to be found." },
[3002] = { title = "The Gordunni Orb", body = "The Gordunni Orb was brought to Uthel'nay in the Darkbriar Lodge in Orgrimmar." },
[2862] = { title = "War on the Woodpaw", body = "Hadoken Swiftstrider in Camp Mojache asked for 10 Woodpaw Gnoll Manes." },
[2863] = { title = "Alpha Strike", body = "Hadoken Swiftstrider asked for the death of 5 Woodpaw Alphas within one hour." },
[2902] = { title = "Woodpaw Investigation", body = "Hadoken Swiftstrider asked for the gnoll battle plans to be found in the gnoll camps south of Camp Mojache." },
[2903] = { title = "The Battle Plans", body = "The Woodpaw Battle Plans were brought to Hadoken Swiftstrider in Camp Mojache." },
[7730] = { title = "Zukk'ash Infestation", body = "Hadoken Swiftstrider in Camp Mojache asked for 20 Zukk'ash Carapaces." },
[7731] = { title = "Stinglasher", body = "Hadoken Swiftstrider asked for the defeat of Stinglasher in the Writhing Deep. Its glands were brought back to Camp Mojache." },
[7732] = { title = "Zukk'ash Report", body = "Hadoken Swiftstrider sent the Camp Mojache Zukk'ash Report to Zilzibin Drumlore in the Drag of Orgrimmar." },
[3121] = { title = "A Strange Request", body = "Witch Doctor Uzer'i sent a Shrunken Head to Neeru Fireblade in Orgrimmar." },
[3122] = { title = "Return to Witch Doctor Uzer'i", body = "Neeru Fireblade gave Neeru's Herb Pouch. It was delivered to Witch Doctor Uzer'i in Feralas." },
[3123] = { title = "Testing the Vessel", body = "Witch Doctor Uzer'i asked for 10 Wildkin Muiseks from the Hinterlands, captured with the Muisek Vessel." },
[3124] = { title = "Hippogryph Muisek", body = "Witch Doctor Uzer'i asked for 10 Frayfeather Hippogryphs to be killed and captured with the Muisek Vessel." },
[3125] = { title = "Faerie Dragon Muisek", body = "Witch Doctor Uzer'i asked for 8 Sprite Darters or Sprite Dragons to be killed and captured with the Muisek Vessel." },
[3126] = { title = "Treant Muisek", body = "Witch Doctor Uzer'i asked for 3 Wandering Forest Walkers to be killed and captured with the Muisek Vessel." },
[3127] = { title = "Mountain Giant Muisek", body = "Witch Doctor Uzer'i asked for 7 Land Walkers or Cliff Giants to be killed and captured with the Muisek Vessel." },
[3128] = { title = "Natural Materials", body = "Witch Doctor Uzer'i in Camp Mojache asked for 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew and 40 Metallic Fragments." },
[3129] = { title = "Weapons of Spirit", body = "Witch Doctor Uzer'i prepared the weapons in Camp Mojache." },
[2933] = { title = "Venom Bottles", body = "A Venom Bottle was brought to an apothecary in Tarren Mill." },
[2934] = { title = "Undamaged Venom Sac", body = "Apothecary Lydon in Tarren Mill asked for an Undamaged Venom Sac." },
[2935] = { title = "Consult Master Gadrin", body = "Apothecary Lydon sent the word to Master Gadrin in Sen'jin Village." },
[2936] = { title = "The Spider God", body = "Master Gadrin asked for a reading of the Tablet of Theka. It gave the name of the Witherbark spider god." },
[2937] = { title = "Summoning Shadra", body = "Master Gadrin asked for the defeat of Shadra at the altar of Shadra'Alor. Her venom was brought to Apothecary Lydon in Tarren Mill." },
[2938] = { title = "Venom to the Undercity", body = "Apothecary Lydon sent Faranell's Parcel to Master Apothecary Faranell in the Undercity." },
[649] = { title = "Ripple Recovery", body = "Dran Droffers sent the word to Malton Droffers in Orgrimmar." },
[650] = { title = "Ripple Recovery", body = "Malton Droffers sent the word to Gilveradin Sunchaser at the camp in the Hinterlands." },
[77] = { title = "A Sticky Situation", body = "Gilveradin Sunchaser asked for 10 bottles of Hinterlands Honey Ripple from the crates around the abandoned Horde base in Skulk Rock." },
[81] = { title = "Ripple Delivery", body = "Gilveradin Sunchaser gave a barrel. It was delivered to Dran Droffers in Orgrimmar." },
[2742] = { title = "Rin'ji is Trapped!", body = "Rin'ji asked for an escort out of the Quel'Danil Lodge. His hidden secret lay at the Overlook Cliffs to the east." },
[2782] = { title = "Rin'ji's Secret", body = "Rin'ji's tablet went to Oran Snakewrithe in the Magic Quarter of the Undercity." },
[8273] = { title = "Oran's Gratitude", body = "Oran Snakewrithe asked for a report at Revantusk Village in the Hinterlands." },
[7841] = { title = "Message to the Wildhammer", body = "Otho Moji'ko at Revantusk Village asked for the death of 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksmen and 15 Highvale Rangers at the Quel'Danil Lodge." },
[7842] = { title = "Another Message to the Wildhammer", body = "Otho Moji'ko asked for 10 Long Elegant Feathers from the gryphons of the Hinterlands." },
[7843] = { title = "The Final Message to the Wildhammer", body = "Otho Moji'ko asked for the Final Message to the Wildhammer to be placed by the well in the center of Aerie Peak." },
[7845] = { title = "Kidnapped Elder Torntusk!", body = "Primal Torntusk at Revantusk Village asked for Elder Torntusk to be rescued from Jintha'alor." },
[7846] = { title = "Recover the Key!", body = "Elder Torntusk at Jintha'alor asked for the death of Hitah'ya the Keeper. The Shackle Key came from the kill." },
[7847] = { title = "Return to Primal Torntusk", body = "Elder Torntusk sent the news of the rescue to Primal Torntusk at Revantusk Village." },
[2784] = { title = "Fall From Grace", body = "The Fallen Hero of the Horde told the story of the fall." },
[2621] = { title = "The Disgraced One", body = "The Fallen Hero of the Horde sent the word to Dispatch Commander Ruag in Stonard." },
[2622] = { title = "The Missing Orders", body = "Dispatch Commander Ruag sent the word to Bengor." },
[2623] = { title = "The Swamp Talker", body = "Bengor asked for the Warchief's Orders. They were returned to the Fallen Hero of the Horde." },
[3517] = { title = "Stealing Knowledge", body = "Jediga in Azshara asked for the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri and the Tablet of Sael'hai." },
[3518] = { title = "Delivery to Magatha", body = "Jediga sent the Tablet of Beth'Amara to Magatha Grimtotem in Thunder Bluff." },
[3562] = { title = "Magatha's Payment to Jediga", body = "Magatha Grimtotem gave a note. It was delivered to Jediga in Azshara." },
[3541] = { title = "Delivery to Jes'rimon", body = "Jediga sent the Tablet of Jin'yael to Jes'rimon in Orgrimmar." },
[3563] = { title = "Jes'rimon's Payment to Jediga", body = "Jes'rimon gave a note. It was delivered to Jediga in Azshara." },
[3542] = { title = "Delivery to Andron Gant", body = "Jediga sent the Tablet of Markri to Andron Gant in the Undercity." },
[3564] = { title = "Andron's Payment to Jediga", body = "Andron Gant gave a note. It was delivered to Jediga in Azshara." },
[3561] = { title = "Delivery to Archmage Xylem", body = "Jediga sent the Tablet of Sael'hai to Archmage Xylem in Azshara." },
[3565] = { title = "Xylem's Payment to Jediga", body = "Archmage Xylem gave a note. It was delivered to Jediga in Azshara." },
[4145] = { title = "Larion and Muigin", body = "Larion at Marshal's Refuge asked for the death of 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers." },
[4147] = { title = "Marvon's Workshop", body = "Larion sent the word to Liv Rizzlefix at the workshop of Marvon Rivetseeker in Ratchet." },
[4146] = { title = "Zapper Fuel", body = "Liv Rizzlefix gave the Unloaded Zapper. It was delivered with 5 samples of Atal'ai Haze to Larion at Marshal's Refuge." },
[4148] = { title = "Bloodpetal Zapper", body = "Larion in Un'Goro Crater gave this task and took the hand-in. The task has no objective text of its own." },
[6605] = { title = "A Strange One", body = "Harlo Wigglesworth sent the word to Winna Hazzard in Felwood." },
[4505] = { title = "Well of Corruption", body = "Winna Hazzard asked for a sample of corrupted water from the moonwell of the Jadefire Satyrs. It was brought to Winna Hazzard at Bloodvenom Post." },
[4506] = { title = "Corrupted Sabers", body = "Winna Hazzard gave a kitten. It was released at the corrupted moonwell and brought back to Winna Hazzard." },
[4521] = { title = "Wild Guardians", body = "Trull Failbane in Felwood asked for the death of 15 Raging Owlbeasts and 15 Ragged Owlbeasts." },
[4741] = { title = "Wild Guardians", body = "Trull Failbane asked for 13 Moontouched Owlbeasts to be hunted in Felwood." },
[4721] = { title = "Wild Guardians", body = "Trull Failbane asked for 10 Berserk Owlbeasts to be hunted in Winterspring." },
[5054] = { title = "Ursius of the Shardtooth", body = "Storm Shadowhoof at Everlook in Winterspring asked for the death of Ursius." },
[5055] = { title = "Brumeran of the Chillwind", body = "Storm Shadowhoof asked for the death of Brumeran at Everlook in Winterspring." },
[5056] = { title = "Shy-Rotam", body = "Storm Shadowhoof asked for the defeat of Shy-Rotam at Everlook in Winterspring." },
[5093] = { title = "A Call to Arms: The Plaguelands!", body = "Warcaller Gorlach sent the word to High Executor Derrington at the Bulwark, east of Tirisfal Glades and the Undercity." },
[5096] = { title = "Scarlet Diversions", body = "High Executor Derrington asked for the destruction of the command tent of the Scarlet Crusade between Felstone Field and Dalson's Tears. The Scourge banner was placed at the camp." },
[5098] = { title = "All Along the Watchtowers", body = "High Executor Derrington asked for each of the 4 towers in Andorhal to be marked with the Beacon Torch. The torch went back to the Bulwark." },
[105] = { title = "Alas, Andorhal", body = "High Executor Derrington asked for Araj's Phylactery Shard at the Bulwark in the Western Plaguelands." },
[5228] = { title = "The Scourge Cauldrons", body = "High Executor Derrington sent the word to Shadow Priestess Vandis at the Bulwark in the Western Plaguelands." },
[5229] = { title = "Target: Felstone Field", body = "Shadow Priestess Vandis asked for the defeat of the Cauldron Lord at Felstone Field and for a poison sample from the cauldron." },
[5230] = { title = "Return to the Bulwark", body = "The Filled Felstone Field Bottle was brought to Shadow Priestess Vandis at the Bulwark." },
[5231] = { title = "Target: Dalson's Tears", body = "Shadow Priestess Vandis asked for the defeat of the Cauldron Lord at Dalson's Tears and for a poison sample from the cauldron." },
[5232] = { title = "Return to the Bulwark", body = "The Filled Dalson's Tears Bottle was brought to Shadow Priestess Vandis at the Bulwark." },
[5233] = { title = "Target: Writhing Haunt", body = "Shadow Priestess Vandis asked for the defeat of the Cauldron Lord at the Writhing Haunt and for a poison sample from the cauldron." },
[5961] = { title = "The Champion of the Banshee Queen", body = "Lady Sylvanas Windrunner sent the word to Nathanos Blightcaller, who had taken up residence at the Marris Stead in the Eastern Plaguelands." },
[6133] = { title = "The Ranger Lord's Behest", body = "Nathanos Blightcaller asked for the Quel'Thalas Registry from the Quel'Lithien Lodge, and for the death of 8 Rangers, 8 Pathstriders and 8 Woodsmen." },
[6022] = { title = "To Kill With Purpose", body = "Nathanos Blightcaller asked for the death of the Scourge at Corin's Crossing and for 7 pieces of Living Rot, ground into Coagulated Rot with the Mortar and Pestle. A time limit of 10 minutes applied." },
[6042] = { title = "Un-Life's Little Annoyances", body = "Nathanos Blightcaller asked for the death of 20 Noxious Plaguebats and 10 Monstrous Plaguebats." },
[6136] = { title = "The Corpulent One", body = "Nathanos Blightcaller asked for the destruction of Borelgore in the northern wastes of the Eastern Plaguelands." },
[6135] = { title = "Duskwing", body = "Nathanos Blightcaller asked for the death of Duskwing and for a Patch of Duskwing's Fur. Reports placed Duskwing north of Marris Stead." },
[6144] = { title = "The Call to Command", body = "Nathanos Blightcaller sent the word to Varimathras in the Undercity." },
[6145] = { title = "The Crimson Courier", body = "Varimathras sent the word back to the Eastern Plaguelands. The Crimson Courier was killed, and the Grand Crusader's Command went to Nathanos Blightcaller." },
[6146] = { title = "Nathanos' Ruse", body = "Nathanos Blightcaller sent the Grand Crusader's Command to Crusader Lord Valdelmar at Tyr's Hand. A bite of the Rotten Apple gave the guise of the Scarlet Crusade for the delivery." },
[6147] = { title = "Return to Nathanos", body = "Crusader Lord Valdelmar gave new information. It was brought to Nathanos Blightcaller." },
[6148] = { title = "The Scarlet Oracle, Demetria", body = "Nathanos Blightcaller asked for the death of the Scarlet Oracle, Demetria, on the road from Tyr's Hand to Stratholme." },
}
for id, e in pairs(E) do ns.JournalEntries[id] = e end

local P = {
crossroads = { title = "Epilogue: The Crossroads", body = "Thork at the Crossroads gave the tasks of this chain. It began with the Razormane tribe and ended with the Supply Crates, which were returned to Thork in the Barrens." },
fungal_spores = { title = "Epilogue: Fungal Spores", body = "Apothecary Helbrim at the Crossroads gave the tasks of this chain. It began with 4 Fungal Spores and ended with deliveries to Apothecary Zamah in Thunder Bluff and to Wharfmaster Dizzywig in Ratchet." },
raptor_thieves = { title = "Epilogue: Raptor Thieves", body = "Gazrog at the Crossroads gave the tasks of this chain. It began with 12 Raptor Heads and ended with the Stolen Silver, which was brought to Gazrog in the Crossroads." },
kolkar_leaders = { title = "Epilogue: Kolkar Leaders", body = "Regthar Deathgate, west of the Crossroads, gave the tasks of this chain. It began with 15 Centaur Bracers and ended with a Piece of Krom'zar's Banner." },
echeyakee = { title = "Epilogue: Echeyakee", body = "Sergra Darkthorn in the Crossroads gave the first tasks of this chain. Jorn Skyseer at Camp Taurajo gave the next ones, and the chain ended with the Heart of Isha Awak, which was brought to Mahren Skyseer." },
barrens_oases = { title = "Epilogue: The Barrens Oases", body = "Arch Druid Hamuul Runetotem in Thunder Bluff began this chain, and Tonga Runetotem at the Crossroads gave its tasks. The chain ended with a message for Mura Runetotem in the Sepulcher, in Silverpine Forest." },
harpy_raiders = { title = "Epilogue: Harpy Raiders", body = "Darsok Swiftdagger at the Crossroads gave the tasks of this chain. It began with 8 Witchwing Talons and ended with a letter for Witch Doctor Jin'Zil in Malaka'Jin, in the Stonetalon Mountains." },
northwatch = { title = "Epilogue: Northwatch", body = "Captain Thalo'thas Brightsun in Ratchet and Gilthares Firebough gave the tasks of this chain. It began with the Theramore Medals and ended with Gilthares Firebough, escorted back to Captain Brightsun in Ratchet." },
tribes_at_war = { title = "Epilogue: Tribes at War", body = "Mangletooth in Camp Taurajo gave the tasks of this chain, from the Bristlebacks to the Blood Shards of Agamaggan. It ended with Lok's Skull for Thork at the Crossroads in the Barrens." },
gann = { title = "Epilogue: Gann's Reclamation", body = "Gann Stonespire gave the tasks of this chain. It began with Khazgorm's Journal and ended with the destruction of the flying machine at Bael Modan." },
warsong = { title = "Epilogue: The Warsong Reports", body = "Thork and Kadrak gave the tasks of this chain. It began with a report to Kadrak at the watch tower in northern Barrens and ended with the updates of the Warsong Reports for Kadrak." },
yenniku = { title = "Epilogue: Yenniku", body = "Nimboya and Kin'weelay gave the tasks of this chain, and the Bubbling Cauldron at the Grom'gol Base Camp opened several of them. It ended with the Filled Soul Gem for Nimboya." },
bloodscalp_trolls = { title = "Epilogue: Troll Hunts in Stranglethorn", body = "Kin'weelay gave the necklace and Tablet Shard tasks of this chain at the Grom'gol Base Camp. Nimboya gave the last one, and it ended with Zengu in Hammerfall in the Arathi Highlands." },
grom_gol = { title = "Epilogue: Grom'gol Base Camp", body = "Commander Aggro'gosh and Far Seer Mok'thardin gave the tasks of this chain at the Grom'gol base camp. It ended with Holy Spring Water for Far Seer Mok'thardin and the death of 10 Naga Explorers." },
egg_hunt = { title = "Epilogue: Egg Hunt", body = "Korran at the Crossroads gave the only task of this chain. It was 12 Silithid Eggs and the Digging Claw." },
weapons_of_choice = { title = "Epilogue: Weapons of Choice", body = "Tatternack Steelforge at Camp Taurajo gave the tasks of this chain. It began with weapons of the Razormane tribe and ended with an Unrefined Ore Sample." },
tear_of_the_moons = { title = "Epilogue: The Tear of the Moons", body = "Feegly the Exiled gave the only task of this chain in the Barrens. It was the Tear of the Moons." },
ashenvale_hunt = { title = "Epilogue: The Ashenvale Hunt", body = "Jorn Skyseer and Senani Thunderheart gave the tasks of this chain. It began with the word of the hunt and ended with the report to Senani Thunderheart at Splintertree Post, after the claw, the paw and the head were brought in." },
cenarius_legacy = { title = "Epilogue: Cenarius' Legacy", body = "Braelyn Firehand near Sun Rock Retreat gave the tasks of this chain. It began with Sons and Daughters of Cenarius and ended at the Den on Stonetalon Peak, where the Talon Den Hoard was opened." },
freewind_post = { title = "Epilogue: Message to Freewind Post", body = "Brave Moonhorn and Cliffwatcher Longhorn gave the tasks of this chain at Freewind Post. It began with an Urgent Message and ended with the three Secret Notes of Darkcloud Pinnacle." },
alien_egg = { title = "Epilogue: Alien Egg", body = "Hagar Lightninghoof, Motega Firemane and Magatha Grimtotem gave the tasks of this chain. It began with the Alien Egg at Freewind Post and ended with the death of Arikara, reported to Motega Firemane in Whitereach Post." },
corrupter = { title = "Epilogue: The Corrupter", body = "Maurin Bonesplitter and Takata Steelblade gave the tasks of this chain in Desolace. It began with the Flayed Demon Skin and ended with the death of Lord Azrethoc and Jugkar Grim'rod." },
battle_of_hillsbrad = { title = "Epilogue: Battle of Hillsbrad", body = "High Executor Darthalia in Tarren Mill gave the tasks of this chain. It began with the farmers of Hillsbrad and ended with a Sealed Commendation for Varimathras in the Undercity." },
hillsbrad_rescue = { title = "Epilogue: The Rescue", body = "Krusk in Tarren Mill gave the tasks of this chain. It began with the rescue of Drull and Tog'thar and ended with Taretha's pendant, which Elysa gave and which was returned to Krusk." },
elixir_of_agony = { title = "Epilogue: Elixir of Agony", body = "Apothecary Lydon in Tarren Mill and Master Apothecary Faranell in the Undercity gave the tasks of this chain. It began with 6 Mudsnout Blossoms and ended with the Tainted Keg, placed on the rug for the captured farmers." },
swarm_grows = { title = "Epilogue: The Swarm Grows", body = "Korran and Belgrom Rockmaul sent the word of this chain from the Barrens through Orgrimmar to Moktar Krin in Thousand Needles. It ended with the death of Silithid Searchers, Hive Drones and Invaders." },
hammerfall = { title = "Epilogue: Hammerfall", body = "Gor'mul and Tor'gan gave the tasks of this chain in Hammerfall in the Arathi Highlands. It began with the word to Tor'gan and ended with a last word with Tor'gan, after Tor'gan's orb was given to Gor'mul." },
lost_report = { title = "Epilogue: The Lost Report", body = "Nazeer Bloodpike in Brackenwall Village and Zor Lonetree gave the tasks of this chain. It began with the Spy's Report and ended with a report to Zor Lonetree, after the Jeweled Pendant went to Orgrimmar." },
black_shield = { title = "Epilogue: The Black Shield", body = "Krog and Do'gol in Brackenwall Village gave the tasks of this chain. It began with the Blackened Iron Shield and ended with the word back to Krog after 5 Acidic Venom Sacs were brought." },
hammer_may_fall = { title = "Epilogue: The Hammer May Fall", body = "Tallow, Drum Fel and Korin Fel gave the tasks of this chain, from Hillsbrad Foothills to the Hammerfall outpost in the Arathi Highlands. It ended with the head of Or'Kalar, brought to Korin Fel." },
trollbane = { title = "Epilogue: Trollbane", body = "Zengu in Hammerfall gave the tasks of this chain, and Tor'gan joined it for two of them. It began with the Sigil of Strom and ended with Trol'kalar, delivered to Zengu from Trollbane's tomb in Stromgarde." },
lack_of_surplus = { title = "Epilogue: Lack of Surplus", body = "Dar, Tok'Kar and Katar gave the tasks of this chain in the Swamp of Sorrows. It began with Unprepared Sawtooth Flanks and ended with the death of Marsh Inkspewers, Flesheaters and Oracles." },
brood_of_onyxia = { title = "Epilogue: The Brood of Onyxia", body = "Draz'Zilb and Overlord Mok'Morokk gave the tasks of this chain in Brackenwall Village. It began with Searing Tongues and Hearts and ended with the defeat of Overlord Mok'Morokk." },
pool_of_tears = { title = "Epilogue: Pool of Tears", body = "Fel'zerul in Stonard gave the tasks of this chain. It began with 10 Atal'ai Artifacts, passed through the Atal'ai Exile in the Hinterlands, and ended with 20 Fetishes of Hakkar." },
new_cloak = { title = "Epilogue: A New Cloak's Sheen", body = "Krueg Skullsplitter in Camp Mojache gave the tasks of this chain. It began with Iridescent Sprite Darter Wings and ended with a Crate of Grimtotem Horns for Belgrom Rockmaul in Orgrimmar." },
ogres_of_feralas = { title = "Epilogue: The Ogres of Feralas", body = "Belgrom Rockmaul and Rok Orhan gave the tasks of this chain. It began in Orgrimmar and ended in Camp Mojache with the death of Gordunni Shaman, Warlocks and Maulers." },
gordunni = { title = "Epilogue: The Gordunni Scroll", body = "Rok Orhan in Camp Mojache gave the tasks of this chain. It began with the Gordunni Scroll and ended with the Gordunni Orb, brought to Uthel'nay in the Darkbriar Lodge in Orgrimmar." },
woodpaw = { title = "Epilogue: War on the Woodpaw", body = "Hadoken Swiftstrider in Camp Mojache gave the tasks of this chain. It began with Woodpaw Gnoll Manes and ended with the Camp Mojache Zukk'ash Report for Zilzibin Drumlore in Orgrimmar." },
strange_request = { title = "Epilogue: A Strange Request", body = "Witch Doctor Uzer'i gave the tasks of this chain in Feralas, and Neeru Fireblade in Orgrimmar gave one of them. It began with a Shrunken Head and ended with the weapons prepared in Camp Mojache." },
venom_bottles = { title = "Epilogue: Venom Bottles", body = "Apothecary Lydon and Master Gadrin gave the tasks of this chain. It began with a Venom Bottle in Tarren Mill and ended with Faranell's Parcel for Master Apothecary Faranell in the Undercity, after the defeat of Shadra." },
ripple = { title = "Epilogue: Ripple Recovery", body = "Dran Droffers, Malton Droffers and Gilveradin Sunchaser gave the tasks of this chain. It began in Orgrimmar, went to the camp in the Hinterlands, and ended with a barrel delivered to Dran Droffers." },
rinji = { title = "Epilogue: Rin'ji is Trapped!", body = "Rin'ji and Oran Snakewrithe gave the tasks of this chain. It began with the escort from the Quel'Danil Lodge and ended with a report to Oran at Revantusk Village in the Hinterlands." },
wildhammer_messages = { title = "Epilogue: Message to the Wildhammer", body = "Otho Moji'ko at Revantusk Village gave the tasks of this chain. It began with the death of Highvale elves and ended with the Final Message to the Wildhammer, placed by the well in Aerie Peak." },
torntusk = { title = "Epilogue: Kidnapped Elder Torntusk!", body = "Primal Torntusk and Elder Torntusk gave the tasks of this chain. It began at Revantusk Village and ended with the news of the rescue from Jintha'alor, which was returned to Primal Torntusk." },
fall_from_grace = { title = "Epilogue: Fall From Grace", body = "The Fallen Hero of the Horde, Dispatch Commander Ruag and Bengor gave the tasks of this chain. It began with the story of the fall and ended with the Warchief's Orders, returned to the Fallen Hero of the Horde." },
stealing_knowledge = { title = "Epilogue: Stealing Knowledge", body = "Jediga in Azshara gave the tasks of this chain. It began with 4 tablets and ended with 4 notes of payment, one each from Magatha Grimtotem, Jes'rimon, Andron Gant and Archmage Xylem." },
marvons_workshop = { title = "Epilogue: Larion and Muigin", body = "Larion at Marshal's Refuge and Liv Rizzlefix gave the tasks of this chain. It began with Bloodpetal creatures and ended with the Bloodpetal Zapper, brought to Larion in Un'Goro Crater." },
strange_one = { title = "Epilogue: A Strange One", body = "Harlo Wigglesworth and Winna Hazzard gave the tasks of this chain. It began in Winterspring and ended in Felwood with Winna's kitten, taken to the corrupted moonwell and brought back to Winna Hazzard." },
wild_guardians = { title = "Epilogue: Wild Guardians", body = "Trull Failbane gave the tasks of this chain in Felwood. It began with Raging and Ragged Owlbeasts and ended with Berserk Owlbeasts in Winterspring." },
shardtooth = { title = "Epilogue: Ursius of the Shardtooth", body = "Storm Shadowhoof at Everlook in Winterspring gave the tasks of this chain. It began with the death of Ursius and ended with the defeat of Shy-Rotam." },
plaguelands = { title = "Epilogue: A Call to Arms: The Plaguelands!", body = "Warcaller Gorlach in Orgrimmar gave the first task of this chain. High Executor Derrington and Shadow Priestess Vandis gave the other tasks at the Bulwark in the Western Plaguelands. It ended with the poison samples of Felstone Field, Dalson's Tears and the Writhing Haunt." },
ranger_lord = { title = "Epilogue: The Ranger Lord's Behest", body = "Lady Sylvanas Windrunner sent the word of this chain, and Nathanos Blightcaller in the Eastern Plaguelands gave its tasks. It began with the word to Nathanos Blightcaller, went on with the Quel'Thalas Registry and ended with the death of Duskwing." },
nathanos = { title = "Epilogue: The Call to Command", body = "Nathanos Blightcaller and Varimathras gave the tasks of this chain. It began with a word for the Undercity and ended with the death of the Scarlet Oracle, Demetria, on the road from Tyr's Hand to Stratholme." },
}
for id, e in pairs(P) do ns.JournalEpilogues[id] = e end
